package FakeCygwin;
use strict;
use warnings;
no warnings 'redefine';
# Cygwin's two path subs as MSYS perl has them: C:\x reads as <top>/c/x, and <top>/c/x as C:\x (a trailing / kept as \)
my $top = '$TMP/cyg';
sub Cygwin::win_to_posix_path { (my $x = $_[0]) =~ tr{\\}{/}; $x =~ s{\A([A-Za-z]):}{$top . '/' . lc $1}e; return $x }
sub Cygwin::posix_to_win_path { my $x = $_[0]; return $x unless $x =~ s{\A\Q$top\E/([A-Za-z])(?=/|\z)}{uc($1) . ':'}e; $x .= '/' if $x =~ m{\A[A-Z]:\z}; $x =~ tr{/}{\\}; return $x }
1;
